import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Module: handl_discovery","description":"","frontmatter":{},"headers":[],"relativePath":"api/discovery/handl_discovery/handl_discovery.md","filePath":"api/discovery/handl_discovery/handl_discovery.md"}`),a={name:`api/discovery/handl_discovery/handl_discovery.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p><strong>handl_discovery</strong></p><h1 id="module-handl-discovery" tabindex="-1">Module: handl_discovery <a class="header-anchor" href="#module-handl-discovery" aria-label="Permalink to “Module: handl_discovery”">​</a></h1><h2 id="contents" tabindex="-1">Contents <a class="header-anchor" href="#contents" aria-label="Permalink to “Contents”">​</a></h2><p><strong>Modules</strong></p><ul><li><a href="#codec"><code>codec</code></a> - The JSON wire codec — <code>ir.term_to_data</code> / <code>rulecache._enc_binding</code></li><li><a href="#enumerate"><code>enumerate</code></a> - Bounded Cantor enumeration — the generic half of the spec&#39;s</li><li><a href="#evidence"><code>evidence</code></a> - The evidence leg — premise-anchored derivability, guarded-region</li><li><a href="#gauntlet"><code>gauntlet</code></a> - The admission gauntlet — <code>evidence.run_gauntlet</code>&#39;s stage pipeline</li><li><a href="#rulecache"><code>rulecache</code></a> - Persistent cache for synthesized rewrite rules —</li><li><a href="#terms"><code>terms</code></a> - Term-level pattern machinery — the pure-compute half of the</li></ul><hr><h2 id="module-codec" tabindex="-1">Module: codec <a class="header-anchor" href="#module-codec" aria-label="Permalink to “Module: codec”">​</a></h2><p>The JSON wire codec — <code>ir.term_to_data</code> / <code>rulecache._enc_binding</code> ported for the generic <code>Term</code>/<code>ReExpr</code> shapes.</p><p>The scheme mirrors the spec&#39;s canonical form where it applies:</p><ul><li><code>{&quot;mvar&quot;: name}</code> — a pattern metavariable (<code>Term::Var</code>).</li><li><code>{&quot;leaf&quot;: key}</code> — a concrete leaf (<code>Term::Leaf</code>). The spec&#39;s typed leaf kinds (<code>Const</code>/<code>Var</code>/<code>Param</code>) ride the <em>key</em> in this substrate — the bridge&#39;s self-describing-leaf convention.</li><li><code>{&quot;op&quot;: name, &quot;args&quot;: [...], &quot;attrs&quot;: {k: v}}</code> — an <code>Op</code> node. Attr entries are the value&#39;s <code>AttrValue</code> JSON form for <code>TermAttr::Lit</code>, and <code>{&quot;amvar&quot;: name}</code> for <code>TermAttr::Meta</code> — the typed port of the spec&#39;s bare-string ambiguity (a Python string attr is both &quot;literal string&quot; and &quot;metavar reference&quot;; here the two are distinct, strictly more honest).</li></ul><p>Binding maps (<code>ReExpr</code> / fired substitutions) encode as the spec&#39;s <code>[key, {&quot;t&quot;: term} | {&quot;a&quot;: attr}]</code> pair lists.</p><h2 id="module-enumerate" tabindex="-1">Module: enumerate <a class="header-anchor" href="#module-enumerate" aria-label="Permalink to “Module: enumerate”">​</a></h2><p>Bounded Cantor enumeration — the generic half of the spec&#39;s <code>oracle</code> binding machinery.</p><p>The domain legs of <code>oracle._binding_envs</code> (leaf binding banks, shape-valid attr domains, <code>JOINT_SHAPES</code>) stay domain data; what this module ports is the <em>fair enumeration skeleton</em> underneath:</p><ul><li>[<code>combos_at_sum</code>] / [<code>diag_product</code>] — <code>oracle._combos_at_sum</code> / <code>oracle._diag_product</code>: <code>product(*lists)</code> in Cantor index-sum order. A cap truncates a <em>corner</em> of the product space, not a whole dimension — the ordering is the contract.</li><li>[<code>LazySeq</code>] — <code>oracle._LazySeq</code>: indexed pull over an iterator, materializing on demand only.</li><li>[<code>diag_groups</code>] — <code>oracle._diag_groups</code>: the ragged <code>(viewed × attr)</code> product interleaved by <code>v + a</code>.</li><li>[<code>binding_envs</code>] — <code>oracle._binding_envs</code>: the outer <code>(base, free-combo)</code> diagonal with lazy base pull and the [<code>MAX_BINDING_ENVS</code>] work bound.</li><li>[<code>escalate_limit</code>] — <code>oracle.escalate_limit</code>: the selective guarded-cap policy.</li></ul><h2 id="module-evidence" tabindex="-1">Module: evidence <a class="header-anchor" href="#module-evidence" aria-label="Permalink to “Module: evidence”">​</a></h2><p>The evidence leg — premise-anchored derivability, guarded-region sweeps, and the stored-object seam of the spec&#39;s <code>evidence.py</code>.</p><p>Pure compute only: the <em>store</em> is a trait ([<code>ObjectStore</code>]), the bare-record rebuild is a trait ([<code>ObjectCodec</code>]), and the numeric oracle is an injected <code>eval</code> closure — the torch truth legs stay in the domain. What is ported:</p><ul><li>[<code>premise_rules</code>] — <code>evidence._premise_rules</code>: a stored object&#39;s transitive premise closure, resolved exactly the way <code>admit_object</code> resolves transport parents — a stored row rebuilt at full declared strength (<code>missing_hooks</code> minus <code>transported</code> empty), walked transitively, cycle-safe. Any shortfall empties the whole closure: a partial premise set is not the derivation the object was minted under.</li><li>[<code>premise_steps_verify</code>] / [<code>premise_credit</code>] — <code>evidence._premise_steps_verify</code> / <code>_premise_credit</code>: the anti-gaming bar — every non-axiom step an anchored derivation <em>invoked</em> must site-verify <code>equal</code> under the injected oracle, or the anchored credit is revoked.</li><li>[<code>site_outcome</code>] / [<code>guarded_evals</code>] / [<code>synth_sites</code>] / [<code>guarded_truth</code>] — <code>evidence._site_outcome</code> / <code>_guarded_evals</code> / <code>_synth_sites</code> / <code>_guarded_truth</code>: the guarded-region sweep (every accepted evaluable binding must be equal, and at least one must exist) with the selective-cap escalation.</li><li>[<code>rebuild_stored</code>] / [<code>admit</code>] — <code>evidence._rebuild_stored</code> / <code>admit_object</code>: the stored-record → live-rule path with guard transport.</li></ul><h2 id="module-gauntlet" tabindex="-1">Module: gauntlet <a class="header-anchor" href="#module-gauntlet" aria-label="Permalink to “Module: gauntlet”">​</a></h2><p>The admission gauntlet — <code>evidence.run_gauntlet</code>&#39;s stage pipeline as a trait-driven structure.</p><p>A stored object earns <code>usable</code> only by clearing the same gates a shipped law cleared, in the spec&#39;s order:</p><ol><li><strong>reconstruct</strong> — the record admits into a live rule;</li><li><strong>full-data</strong> — <code>missing_hooks</code> minus <code>transported</code> is empty;</li><li><strong>measure</strong> — the domain&#39;s measurement pipeline (numeric oracle, <em>premise-anchored</em> derivability, the raw view verdict);</li><li><strong>truth</strong> — unguarded: the measured verdict; guarded: the guarded-region sweep — every accepted evaluable binding equal, at least one existing;</li><li><strong>novelty</strong> — the object is not a library spelling;</li><li><strong>typed-pay</strong> — fires, all well-typed, pays, lowerings agree;</li><li><strong>closure</strong> — bounded closure, no object-attributable cert break;</li><li><strong>cert</strong> — a recorded derivation replays strict.</li></ol><p>The <em>shape</em> is ported; the <em>legs</em> are injected through [<code>GauntletLegs</code>] — the store, the record codec, the base axiom set, the measurement pipeline, the guarded-region sweep, the site oracle, the cert replay, and the auto-cond retry are all domain machinery this skeleton drives but never implements.</p><h2 id="module-rulecache" tabindex="-1">Module: rulecache <a class="header-anchor" href="#module-rulecache" aria-label="Permalink to “Module: rulecache”">​</a></h2><p>Persistent cache for synthesized rewrite rules — <code>catopt_core.rulecache</code>.</p><p>The synthesis engine&#39;s output is pure data: Op-tree lhs/rhs patterns plus <em>hooks</em>. Hooks are not serialized — each guarded rule stores its <em>re-expression spec</em>: the parent pair names and the two substitution maps <code>(pat1, pat2)</code> that map each parent&#39;s metavariables to patterns over the derived rule&#39;s metavars. At load time the composite hooks are rebuilt by re-running [<code>compose_guards</code>] against the parent rules resolved by name — the composition machinery is cheap; it is the search/validation that was expensive.</p><p>Round-trip contract (the spec verbatim):</p><ul><li><strong>Payload-internal parent resolution.</strong> Records decode in stored order and each decoded rule joins the resolver, so a fixpoint mint&#39;s <code>syn_*</code> parents — earlier records of the same payload — resolve inside the payload and a multi-round output round-trips self-contained. A caller rule and a stored record sharing a name resolve to the stored one.</li><li><strong>Guard transport.</strong> A guarded record&#39;s <code>pat1</code>/<code>pat2</code> re-run <code>compose_guards</code> over the resolved parents; the composite <code>derive</code> attaches only when the RHS carries <code>&quot;@i:&quot;</code> placeholders (the spec&#39;s offer/load policy).</li><li><strong>Clean miss, never partial.</strong> A missing parent, a version/key mismatch, or a corrupt file returns <code>None</code> — never a partially-loaded set.</li><li><strong>Honest refusal to store.</strong> A rule carrying hooks without a <code>guard_pats</code> spec is not synthesizer output — <code>store</code>/<code>enc_rule</code> refuse rather than silently dropping its side conditions.</li></ul><h2 id="module-terms" tabindex="-1">Module: terms <a class="header-anchor" href="#module-terms" aria-label="Permalink to “Module: terms”">​</a></h2><p>Term-level pattern machinery — the pure-compute half of the spec&#39;s <code>egraph.terms</code> / <code>meta</code> helpers.</p><p>Ports, by contract:</p><ul><li><code>_term_match</code> — structural match of a pattern against a plain term: [<code>Term::Var</code>] binds subterms (repeated metavars must bind structurally equal terms), [<code>TermAttr::Meta</code>] binds attr values, concrete attr values compare with <code>match_eq</code> (the spec&#39;s match-time numeric leniency).</li><li><code>_term_instantiate</code> ([<code>instantiate_lenient</code>]) — unbound <em>term</em> metavariables are a veto (<code>None</code>, the spec&#39;s <code>KeyError</code>), unbound <em>attr</em> metavariables fall back to their literal name (the spec&#39;s <code>subst.get(&quot;$attr:&quot;+v, v)</code> wart — kept: callers may observe it).</li><li><code>meta.instantiate_pattern</code> ([<code>instantiate_strict</code>]) — any unbound metavariable vetoes.</li><li><code>meta._reexpress_binding</code> / <code>meta._compose_guards</code> / <code>meta._rhs_derive_placeholders</code> — the guard-transport core the rulecache and the object store replay.</li><li>The oracle&#39;s generic pattern introspection — [<code>leaf_metavars</code>], [<code>metavar_parents</code>], [<code>free_mvs</code>] — with the domain&#39;s &quot;viewish&quot; alphabet injected as data.</li></ul>`,33)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};